// concern-bpa: canned-food cards name the can lining and the BPA-free rung; earlier lines stay; no illness claims; source from the archive.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { nonEmpty } from '../../lib/testGuards.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));
const ROOT = new URL('../../../', import.meta.url).pathname;
const pre = JSON.parse(execFileSync('git', ['show', '8d6bcf2:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const card = (id) => { const e = kb.entries.find((x) => x.id === id); assert.ok(e, `${id} missing`); return e; };
const was = (id) => { const e = pre.entries.find((x) => x.id === id); assert.ok(e, `${id} missing before`); return e; };
const SKIP = new Set(['sources', 'aliases', 'asked_as', 'id', 'kind', 'category']);
const strings = (v) => (typeof v === 'string' ? [v] : Array.isArray(v) ? v.flatMap(strings) : v && typeof v === 'object' ? Object.values(v).flatMap(strings) : []);
const fields = (e) => Object.entries(e).filter(([k]) => !SKIP.has(k)).flatMap(([, v]) => strings(v));
const text = (e) => fields(e).join(' \n ');
const urlsOf = (e) => (e.sources || []).map((s) => (typeof s === 'string' ? (s.match(/https?:\S+/) || [])[0] : s.url)).filter(Boolean);
const sentences = (id) => fields(card(id)).flatMap((s) => s.split(/(?<=[.;!?])\s+/));

const FULL = ['canned_soup', 'canned_fish_choosing', 'canned_tuna', 'canned_coconut_milk'];
const PICK = 'pick_canned_tomatoes';
const ALL = [...FULL, PICK];
const HOME = 'beans_dried_vs_canned';
const RUNG = { canned_soup: /fresh or frozen/i, canned_fish_choosing: /fresh or frozen/i, canned_tuna: /fresh or frozen/i, canned_coconut_milk: /\bglass\b/i };
const EWG = 'https://www.ewg.org/research/bpa-canned-food';

const root = join(ROOT, 'docs/sources/concerns');
const archived = new Set();
for (const d of readdirSync(root, { withFileTypes: true }).filter((x) => x.isDirectory())) {
  for (const f of readdirSync(join(root, d.name)).filter((x) => x.endsWith('.md'))) {
    const m = readFileSync(join(root, d.name, f), 'utf8').match(/^url:\s*(\S+)/m);
    if (m) archived.add(m[1]);
  }
}

test('C1 full cards name BPA, the non-can rung and the BPA-free rung', () => {
  for (const id of nonEmpty(FULL, 'full cards', 4)) {
    const t = text(card(id));
    assert.match(t, /\bBPA\b/, `${id} BPA`);
    assert.match(t, RUNG[id], `${id} non-can rung`);
    assert.match(t, /says BPA-free[^.]*over[^.]*says nothing/i, `${id} BPA-free over unlabeled`);
    assert.ok((card(id).buying_tips || []).some((s) => /\bBPA\b/.test(s)), `${id} BPA in a tip`);
  }
});

test('C2 BPA-free is the maker word, no product claim, no acidity claim', () => {
  for (const id of FULL) {
    assert.ok((card(id).watch_out || []).some((s) => /BPA-free/.test(s) && /EWG/.test(s) && /as they wish/i.test(s)), `${id} maker-word watch_out`);
    for (const sent of sentences(id)) {
      if (/\bBPA\b/.test(sent)) assert.doesNotMatch(sent, /\b(contains?|carries|has|have|includes?)\s+(BPA|bisphenol)/i, `${id} claims the product has BPA: ${sent}`);
    }
  }
  assert.doesNotMatch(ALL.map((id) => text(card(id))).join(' ').replace(/high-acid canned food keeps/gi, ''), /acid(ic)?\b|high-acid|tomato\w*[^.]*(leach|migrat)/i, 'acidity claim');
});

test('C3 earlier lines stay and the home card is untouched', () => {
  for (const id of FULL) {
    const a = card(id), b = was(id);
    for (const f of ['buying_tips', 'watch_out']) {
      const now = a[f] || [];
      const old = b[f] || [];
      assert.deepEqual(now.slice(0, old.length), old, `${id}.${f} lost or reordered a line`);
    }
    for (const f of ['decision', 'cart_pick', 'tier_note', 'why', 'short_answer', 'science', 'labels_decoded', 'pick_steps', 'kristy_take']) assert.deepEqual(a[f], b[f], `${id}.${f} changed`);
    assert.equal((a.buying_tips || [])[0], (b.buying_tips || [])[0], `${id} tip0 changed`);
  }
  assert.deepEqual(card(HOME), was(HOME), `${HOME} changed`);
});

test('C4 pick_canned_tomatoes keeps its facts and names BPA-free', () => {
  const d = card(PICK).decision;
  for (const re of [/dented/i, /rusted/i, /swollen/i, /quality mark/i, /BPA-free/]) assert.match(d, re);
  assert.ok(d.split(/\s+/).length <= 20, `decision too long: ${d}`);
  assert.equal(d.split(/(?<=[.!?])\s+/).length, 1, 'decision is more than one sentence');
  assert.deepEqual(Object.keys(card(PICK)).sort(), Object.keys(was(PICK)).sort(), 'pick shape changed');
});

test('C5 sources come from the concern archive', () => {
  nonEmpty([...archived], 'archived urls', 100);
  assert.ok(archived.has(EWG), 'EWG BPA url not in archive');
  for (const id of ALL) {
    const before = new Set(urlsOf(was(id)));
    const urls = nonEmpty(urlsOf(card(id)), `${id} sources`, 1);
    assert.ok(urls.includes(EWG), `${id} does not cite the EWG BPA page`);
    for (const u of before) assert.ok(urls.includes(u), `${id} dropped source ${u}`);
    for (const u of urls) assert.ok(before.has(u) || archived.has(u), `${id} url not archived: ${u}`);
  }
});

test('C6 no illness claims, first person, em dash, price or brand', () => {
  const BAN = /\b(causes?|prevents?|lowers? (the )?risk|cancer|tumou?rs?|toxic\w*|unsafe|safe|safer|harm\w*|risks?|linked to|estrogen\w*|hormon\w*|health\w*|exposure|leach\w*|pregnan\w*|infants?|children)\b/i;
  const BRANDS = /\b(Amy'?s|Hormel|Target|Eden|Trader Joe|Whole Foods|Hain|ConAgra|Muir Glen|Annie|Tyson|Sprouts)\b/; // case-sensitive: 'whole foods' is a common noun
  for (const id of ALL) {
    const t = text(card(id)).replace(/dolphin-safe/gi, '');
    assert.doesNotMatch(t, BAN, `${id} treatment wording`);
    assert.doesNotMatch(t, /\b(I|me|my)\b/, `${id} first person`);
    assert.doesNotMatch(t, /—/, `${id} em dash`);
    assert.doesNotMatch(t, /\$\s?\d|\bprice\b|\bcheap\w*/i, `${id} price wording`);
    assert.doesNotMatch(t, BRANDS, `${id} brand name`);
  }
});

// IC-6b: seafood fronts, "Salmon" and "Shrimp" (docs/ITEM-CARDS-PLAN.md IC-6b). Written by the planner; do not edit.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { ESSENTIALS, projectEntry } from '../../lib/counterCards.js';
import { lintCard, readability, headlineHedge, TIER_NOTE_ORPHANED_PENDING } from '../../lib/counterCardLint.js';
import kb from '../../kristy_perimeter_kb.json' with { type: 'json' };
import doLines from '../../lib/doLines.json' with { type: 'json' };

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '../../..');
const PRE = JSON.parse(execFileSync('git', ['show', '663ca3d:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const now = (id) => kb.entries.find((e) => e.id === id);
const pre = (id) => PRE.entries.find((e) => e.id === id);
const words = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const RULE4 = /healthier|healthiest|better for you|chemically ripened|lowers|exposure/i;
const BATCH = ['salmon_wild_vs_farmed', 'shrimp_imported_vs_domestic', 'seafood_counter', 'smoked_salmon', 'white_fish', 'scallops', 'crab',
  'lobster', 'clams_mussels_oysters', 'canned_tuna', 'canned_fish_choosing', 'mercury_by_fish', 'farmed_fish_by_species', 'seafood_certifications'];
const nonPicksTitled = (t) => kb.entries.filter((e) => e.kind !== 'pick' && e.title === t);
const PENDING = [...TIER_NOTE_ORPHANED_PENDING];
const review = readFileSync(join(ROOT, 'docs/do-lines-review.md'), 'utf8');
const reviewHeadline = (id) => {
  const line = review.split('\n').find((l) => l.startsWith(`| \`${id}\` |`));
  return line ? line.split('|')[3].trim() : null;
};
const urls = (e) => (e?.sources || []).flatMap((s) => JSON.stringify(s).match(/https?:\/\/[^\s"”]+/g) || []);

test('C1 the Salmon card', () => {
  const s = now('salmon_wild_vs_farmed');
  assert.equal(s.title, 'Salmon');
  assert.match(s.decision, /wild/i);
  assert.equal(nonPicksTitled('Salmon').length, 1, 'non-pick "Salmon" count');
  assert.ok(ESSENTIALS.includes('salmon_wild_vs_farmed'));
});

test('C2 the Shrimp card', () => {
  assert.equal(now('shrimp_imported_vs_domestic').title, 'Shrimp');
  assert.equal(nonPicksTitled('Shrimp').length, 1, 'non-pick "Shrimp" count');
});

test('C3 seafood pointers follow the retitles', () => {
  const all = JSON.stringify(kb);
  assert.ok(!all.includes('see Wild vs. farmed salmon'), 'stale salmon pointer');
  assert.ok(!all.includes('see Imported vs. domestic shrimp'), 'stale shrimp pointer');
  assert.ok(all.includes('Wild or farmed: see Salmon.'), 'no repointed salmon pointer');
});

test('C5 seafood fronts and why lines pass', () => {
  const notes = kb.entries.map((e) => String(e.tier_note || '').trim()).filter(Boolean);
  for (const id of BATCH) {
    const e = now(id);
    assert.ok(e, `${id} missing`);
    assert.ok(words(e.decision) <= 14, `${id} front is ${words(e.decision)} words`);
    assert.deepEqual(headlineHedge(e.decision), [], `${id} front hedges`);
    const n = String(e.tier_note || '').trim();
    assert.ok(words(n) >= 5, `${id} tier_note too short`);
    assert.doesNotMatch(n, /[.!?]\s+\S/, `${id} tier_note is more than one sentence`);
    assert.doesNotMatch(n, /\b(I|me|my|mine|we|us|our)\b/, `${id} tier_note first person`);
    assert.notEqual(n.toLowerCase().replace(/[^a-z]/g, ''), String(e.evidence_tier).toLowerCase().replace(/[^a-z]/g, ''), `${id} tier_note is the tier name`);
    assert.equal(notes.filter((x) => x === n).length, 1, `${id} tier_note not unique`);
    assert.ok(!PENDING.includes(id), `${id} still pending`);
    assert.deepEqual(lintCard(projectEntry(e, { doLine: doLines[id] })), [], `${id} lint`);
    assert.deepEqual(readability(e), [], `${id} readability`);
    assert.equal(reviewHeadline(id), e.decision, `${id} review headline differs from KB decision`);
  }
  assert.deepEqual([...ESSENTIALS], ['organic_worth_it_by_type', 'egg_labels', 'salmon_wild_vs_farmed', 'label_front_vs_back',
    'produce_ripeness_by_item', 'beef_grassfed_vs_grainfed', 'judging_meat_at_the_case', 'whole_vs_reduced_fat_milk']);
});

test('C6 claim-lock rule 4', () => {
  for (const id of BATCH) assert.doesNotMatch(`${now(id).decision} ${now(id).tier_note}`, RULE4, id);
});

test('C7 no new seafood URLs', () => {
  let total = 0;
  for (const id of BATCH) {
    const was = new Set(urls(pre(id)));
    if (id === 'seafood_counter') for (const f of ['fresh_vs_previously_frozen_fish', 'fish_freshness_at_counter']) for (const u of urls(pre(f))) was.add(u);
    for (const u of urls(now(id))) { total++; assert.ok(was.has(u), `${id}: new URL ${u} (no seafood archive exists)`); }
  }
  assert.ok(total >= 1, 'batch carries no URLs at all');
});
// K6: readability pass, produce slice 2 plus seafood.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { nonEmpty } from '../../lib/testGuards.js';
import { readability, lintCard } from '../../lib/counterCardLint.js';
import { projectEntry, parseReviewTable, RETIRED } from '../../lib/counterCards.js';
import kb from '../../kristy_perimeter_kb.json' with { type: 'json' };
import pre from './fixtures/kb-pre-readability.json' with { type: 'json' };
import { assertPassRule } from './passRule.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const reviewed = parseReviewTable(readFileSync(join(HERE, '../../../docs/do-lines-review.md'), 'utf8'));

const SLICE = nonEmpty([
  'produce_leafy_greens', 'produce_peppers', 'produce_apples_pears', 'produce_citrus', 'produce_stone_fruit',
  'salmon_wild_vs_farmed', 'shrimp_imported_vs_domestic', 'mercury_by_fish',
  'canned_fish_choosing', 'farmed_fish_by_species', 'seafood_certifications', 'canned_tuna',
], 'the K6 slice', 12);

const oldEntries = pre.entries ?? pre;

for (const id of SLICE) {
  test(`K6 ${id}: readable, lint-clean, pass rule held`, (t) => {
    const now = kb.entries.find((e) => e.id === id);
    const old = oldEntries.find((e) => e.id === id);
    assert.ok(now && old, `${id} missing from the KB or the fixture`);
    assert.deepEqual(readability(now), []);
    assert.deepEqual(lintCard(projectEntry(now, { doLine: reviewed.get(id)?.do || '' })), []);
    assertPassRule(t, old, now);
  });
}

test('K6: IC-6a retired ids are in RETIRED and gone from the KB', () => {
  for (const id of ['fresh_vs_previously_frozen_fish', 'fish_freshness_at_counter']) {
    assert.ok(RETIRED.includes(id), `${id} not in RETIRED`);
    assert.ok(!kb.entries.some((e) => e.id === id), `${id} still in the KB`);
  }
});
// Owns the two-line rewrite's text (docs/CARD-STYLE-SAMPLES.md): every card's decision and
// buying_tips (and egg_labels sources) equal the pin in twoLinePin.js, which older batch tests read through.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { nonEmpty } from '../../lib/testGuards.js';
import { TWO_LINE } from './twoLinePin.js';
import { matchItemToCard } from '../../lib/listMatch.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));

test('every card carries the pinned two-line decision and buying_tips', () => {
  const cards = nonEmpty(kb.entries.filter((e) => e.kind !== 'pick'), 'cards', 180);
  for (const e of cards) {
    assert.ok(TWO_LINE[e.id], `${e.id} has no two-line pin`);
    // Every pinned field, so a field the older tests restore (cart_pick, pick_steps) is still checked live.
    for (const [k, v] of Object.entries(TWO_LINE[e.id])) assert.deepEqual(e[k], v, `${e.id}.${k}`);
  }
  assert.equal(Object.keys(TWO_LINE).length, cards.length, 'a pin for a card that is gone');
});

// Known gap: lintSections L5 makes the chuck pick carry the G1 term, and that term alone outscores
// beef_cuts_basics for beef_grassfed_vs_grainfed (scorePool's top-2 window), so the pick lands uncarded.
// Pinned null so a matcher or wording change that fixes it (or sends it to the wrong card) goes red.
const KNOWN_UNCARDED = new Set(['beef_cuts_basics']);
test('every pinned cart_pick resolves to its own card on the live KB', () => {
  const ids = nonEmpty(Object.keys(TWO_LINE).filter((id) => TWO_LINE[id].cart_pick), 'pinned cart picks', 3);
  for (const id of ids) {
    const m = matchItemToCard(kb.entries.find((e) => e.id === id).cart_pick);
    assert.equal(m ? m.slug ?? m.id ?? m.entry?.id : null, KNOWN_UNCARDED.has(id) ? null : id, `${id} cart_pick`);
  }
});

