/bin/zsh -lc "node --input-type=module - <<'JS'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const currentText = readFileSync('server/kristy_perimeter_kb.json', 'utf8');
const baselineText = execFileSync('git', ['show', 'HEAD:server/kristy_perimeter_kb.json'], { encoding: 'utf8', maxBuffer: 64 << 20 });
const current = JSON.parse(currentText);
const baseline = JSON.parse(baselineText);
const fullIds = ['canned_soup', 'canned_fish_choosing', 'canned_tuna', 'canned_coconut_milk'];
const changed = new Set([...fullIds, 'pick_canned_tomatoes']);
assert.equal(current.entries.length, baseline.entries.length);
const newSentences = [];
for (const old of baseline.entries) {
  const now = current.entries.find(e => e.id === old.id);
  assert.ok(now);
  if ("'!changed.has(old.id)) { assert.deepEqual(now, old, old.id); continue; }
  const allowed = old.kind === '"'pick' ? ['decision', 'sources'] : ['buying_tips', 'watch_out', 'sources'];
  assert.deepEqual(Object.keys(now), Object.keys(old));
  for (const [field, value] of Object.entries(old)) if ("'!allowed.includes(field)) assert.deepEqual(now[field], value, old.id + '"'.' + field);
  assert.deepEqual(now.sources.slice(0, old.sources.length), old.sources);
  assert.equal(now.sources.length, old.sources.length + 1);
  if (old.kind === 'pick') continue;
  for (const field of ['buying_tips', 'watch_out']) {
    assert.deepEqual(now[field].slice(0, old[field].length), old[field]);
    assert.equal(now[field].length - old[field].length, field === 'buying_tips' ? 2 : 1);
    for (const item of now[field].slice(old[field].length)) {
      assert.doesNotMatch(item, /\\b(causes?|prevents?|lowers? (the )?risk|cancer|tumou?rs?|toxic\\w*|unsafe|safe|safer|harm\\w*|risks?|linked to|estrogen\\w*|hormon\\w*|health\\w*|exposure|leach\\w*|pregnan\\w*|infants?|children|acidic|acid|rinse|I|me|my|price|cheap\\w*)\\b|—|\\"'$|'"\\d/i);
      assert.doesNotMatch(item, /\\b(contains?|carries|has|have|includes?)\\s+(BPA|bisphenol)/i);
      for (const sentence of item.split(/(?<=[."'!?])'"\\s+/)) {
        assert.ok(sentence.split(/\\s+/).length <= 20, sentence);
        newSentences.push(sentence);
      }
    }
  }
}
assert.equal(new Set(newSentences).size, newSentences.length, 'repeated BPA sentence');
const rawEntry = text => text.match(/"'^    '"\\{\\n      \"id\": \"beans_dried_vs_canned\",[\\s\\S]*?"'^    '"\\}/m)?.[0];
assert.ok(rawEntry(currentText));
assert.equal(rawEntry(currentText), rawEntry(baselineText), 'home card bytes');
console.log('PASS: only the five intended entries and allowed fields changed; exact append counts; all other entries and home-card bytes preserved.');
console.log('PASS: every new BPA sentence is unique, at most 20 words, and contains no prohibited claims or statistics.');
JS"

