// EVERY FOOD ROW ON THE 26 GETS GUIDANCE — A CARD OR A PICK — AND NOTHING ELSE DOES.
//
// The plan's D4 list (PLAN-step3-picklines.md) is the population a shopper actually writes,
// and it was measured at 19/26 carded with seven bare rows: carrots, broccoli, bell peppers,
// garlic, milk, canned tomatoes, frozen peas. The pick floor (Piece 2) exists to put one
// sentence on those rows; this test is the floor's reach, stated against the list rather than
// against a fixture. It was RED at Piece 2's tip (seven misses) and goes green when the corpus
// carries the picks — that is the prove-fail, recorded in the Piece 3 commit.
//
// Three properties, all through the REAL attach order (`attachCards`), never a re-implementation:
//   1. every food row → a card or a pick (no bare food row)
//   2. every non-food row → neither (Kristy carries anything and judges only food; her
//      silence there is the feature, and a pick on a non-food row is a false claim)
//   3. no pick steals a row a card owns — a pick alias landing on a carded row is the floor
//      running before the ceiling, and where the card's do line already works for that food
//      the pick is dead weight that will shadow it the day the card's alias slips

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { nonEmpty } from './testGuards.js';

import { attachCards, matchItemToCard } from './listMatch.js';
import { pickEntries } from './perimeter.js';
import { lintCard } from './counterCardLint.js';

// Verbatim from the plan (D4) and from `scripts/listMatchProbe.js` REALISTIC_26. The script
// runs at import, so it cannot export the list; a drift between the two is a test failure
// waiting to be noticed, and 26 is asserted below so a truncated copy cannot pass.

test('a state or a count in front of a pick’s own noun still lands', () => {
  // The coverage rule must not eat the rows the picks were authored for.
  assert.equal(attach('frozen peas').pickId, 'pick_frozen_peas');
  // Carrots are a CARD now (P2, produce_root_vegetables); the same rule holds on the card path.
  for (const name of ['2 carrots', 'baby carrots']) {
    assert.equal(attach(name).cardSlug, 'produce_root_vegetables', name);
  }
});

test('every pick in the corpus passes the lint', () => {
  for (const p of nonEmpty(pickEntries(), 'picks')) assert.deepEqual(lintCard(p), [], p.id);
});

test('an inert modifier in front of a pick’s or card’s noun still lands it', () => {
  const bare = MODIFIED_ROWS.filter((name) => { const r = attach(name); return !r.pickId && !r.cardSlug; });
  assert.deepEqual(bare, [], `modified rows that went bare: ${bare.join(', ')}`);
// served by a counter door; it travels on the row. So it clears a different bar from a
// card, and a stricter one, because nothing downstream re-reads it: no tier sentence says
// what kind of claim it is, no depth carries the evidence, no `why` explains it. The line
// has to be true on its face, which means it may only describe what a shopper can SEE,
// FEEL, SMELL or READ on the food or its label — what happens to the food, never to the
// body.
//
// THE VETO VOCABULARY IS EXPLICIT, like IMPERATIVE_VERBS, and for the same reason: a
// part-of-speech judgment about "is this sentence about the body" cannot be reviewed, and a
// list can. Matching is by word boundary, case-insensitive, base form plus `s`/`es` (a
// plural or a third person) and `ing` (the participle a claim hides in: "boosting",
// "supporting"). It does NOT reach into `ed` on purpose: "cured" and "treated" are
// processing words on the meat and produce counters ("dry-cured", "treated with wax") and
// vetoing them would cost the mechanical line the list exists to allow. The outcome nouns
// are the first net — a health claim names the thing it claims to help, and "lowers blood
// sugar" trips on `blood` and `sugar` before it ever needs `lower` — so the verb list is
// the second net, not the only one. Adding a word stays a deliberate act.
//
// KNOWN COST, accepted: the veto is vocabulary, not sense. "weight" is bodily here even
// when an author means the bulb's heft, and "lower" is vetoed even for the lower shelf.
// Write "heavy for its size" and "bottom shelf". A veto that tried to tell the senses
// apart would be a guess dressed as a rule.
//
// `fat` IS NOT ON THE LIST, deliberately. Marbling, the fat cap and "the white should be
// bright, not yellow" are the mechanical read at the meat counter, and a pick for a
// ribeye or a pork shoulder has to be able to say it. "Low-fat" as a health claim trips on
// `health` or the outcome it is attached to, not on the word `fat`.
export const MECHANICAL_VETO = {
  // The body and its outcomes. Any of these in a pick line makes the sentence a claim about
  // the shopper rather than a description of the food, and a claim needs the tier, the
  // source and the depth a pick does not carry. `health` and `immunity` are the nouns the
  // vaguest claims hang on ("for the health benefits", "for immunity").
  body: [
    'heart', 'blood', 'sugar', 'cholesterol', 'inflammation', 'immune', 'immunity', 'gut',
    'digestion', 'weight', 'cancer', 'disease', 'health', 'healthy',
  ],
  // Nutrition vocabulary. A pick may say a yolk is deep orange; it may not say why that is
  // good for you. The moment a line names a nutrient, a calorie, a sodium level or "energy"
  // it is asserting what the food delivers, which is the ingredient KB's job and the verdict
  // engine's, never a list row's. A label's own printed numbers are a scan, not a pick.
  nutrition: [
    'nutrient', 'vitamin', 'mineral', 'protein', 'fiber', 'carb', 'calorie', 'sodium', 'energy',
    'antioxidant', 'detox', 'toxin',
  ],
  // The no-treatment verbs, both directions (non-negotiable #3 is symmetric): a food that
  // treats, cures, prevents, heals, lowers, boosts, fights, protects or supports anything,
  // and a food that CAUSES anything. Kristy is a coach, not a doctor, and a list row is the
  // last place in the app anyone would defer to one.
  treatment: ['treat', 'cure', 'prevent', 'heal', 'lower', 'boost', 'cause', 'fight', 'protect', 'support'],
};


const hasUrl = (s) => /https?:\/\/\S+/.test(String(s || ''));

/**
 * Lint one pick entry. Empty is the passing state.
 * @returns {Array<{code:string, detail:string}>}
 */
// Zero first person (VOICE_SPEC). `I` is case-sensitive so "i" inside nothing trips;
// `us` is lowercase-only so a country of origin ("US grown") does not read as a pronoun.
const hasFirstPerson = (line) =>
  /\bI\b/.test(line) || /\b(me|my|mine|we|our|ours)\b/i.test(line) || /\bus\b/.test(line);

export function lintPick(entry) {
  const out = [];
  const fail = (code, detail) => out.push({ code, detail });
  const e = entry || {};

  // ── Required ──
  for (const f of ['id', 'title', 'category', 'decision']) {
    if (!String(e[f] || '').trim()) fail('PICK_FIELD_MISSING', `a pick needs ${f}`);
  }

  // ── Forbidden ──
  for (const f of Object.keys(e)) {
    if (PICK_FORBIDDEN_FIELDS.has(f)) {
      fail('PICK_FIELD_FORBIDDEN', `"${f}" is a card field — a pick is one sentence, not a card`);
    }
  }

  // ── The food, bare ──
  const title = String(e.title || '').trim();
  if (title && (words(title) > 4 || /[.!?,;:]/.test(title))) {
    fail('PICK_TITLE_NOT_BARE', `the title is the food, bare: "${title}"`);
  }

  // ── Filed under a counter ──
  const category = String(e.category || '').trim();
  if (category) {
    const section = sectionForCategory(category);
    if (!section) fail('PICK_CATEGORY_UNSECTIONED', `"${category}" maps to no counter section`);
    else if (section === NON_AISLE_SECTION) {
      fail('PICK_CATEGORY_NON_AISLE', `"${category}" files under ${section}, which no list row is ever sorted into`);
    }
  }

  // ── Aliases: bare nouns, both numbers ──
  const aliases = Array.isArray(e.aliases) ? e.aliases.map((a) => String(a || '').trim()).filter(Boolean) : [];
  if (aliases.length < 2) {
    fail('PICK_ALIASES_TOO_FEW', `a pick needs at least 2 bare-noun aliases; got ${aliases.length}`);
  }
  const notBare = aliases.filter((a) => !BARE_NOUN.test(a) || words(a) > MAX_PICK_ALIAS_WORDS);
  if (notBare.length) {
    fail(
      'PICK_ALIAS_NOT_BARE',
      `an alias is what a shopper types on a list — lowercase, ≤${MAX_PICK_ALIAS_WORDS} words: ${notBare.map((a) => `"${a}"`).join(', ')}`
    );
  }
  // A state-bearing pick ("Frozen peas") is about the frozen thing. `stateContradicts` is
  // silent when the ROW names no state, so a bare `peas` alias here would attach the frozen
  // line to a fresh row. Every alias carries the state, or the pick does not ship.
  if (title && statesIn(title).size) {
    const stateless = aliases.filter((a) => !statesIn(a).size);
    if (stateless.length) {
      fail(
        'PICK_ALIAS_DROPS_STATE',
        `the title names a state, so every alias must too: ${stateless.map((a) => `"${a}"`).join(', ')}`
      );
    }
  }
  const subjectless = aliases.filter(onlyModifiers);
  if (subjectless.length) {
    fail(
      'PICK_ALIAS_NO_SUBJECT',
      `an alias must name a food, not only describe one: ${subjectless.map((a) => `"${a}"`).join(', ')}`
    );
  }
  const set = new Set(aliases);
  const paired = aliases.some((a) => PLURALS_OF(a).some((p) => set.has(p)));
  if (aliases.length && !paired) {
    fail(
      'PICK_ALIASES_NO_NUMBER_PAIR',
      'aliases must carry a singular AND its plural (s / es / y→ies) — a list says "carrot" and "carrots" both'
    );
  }

  // ── The line ──
  const line = String(e.decision || '').trim();
  if (line) {
    // Exactly one sentence, closed with a period. Two sentences is a card's summary; a
    // fragment is a label.
    const terminals = (line.match(/[.!?](?=\s|$)/g) || []).length;
    if (terminals !== 1 || !line.endsWith('.')) {
      fail('PICK_LINE_NOT_ONE_SENTENCE', `exactly one sentence ending in a period: "${line}"`);
    }
    if (/\?/.test(line)) fail('PICK_LINE_QUESTION', `a pick states, it never asks: "${line}"`);
    if (words(line) > MAX_PICK_WORDS) {
      fail('PICK_LINE_TOO_LONG', `${words(line)}w > ${MAX_PICK_WORDS}: ${line}`);
    }
    if (hasFirstPerson(line)) {
      fail('PICK_LINE_FIRST_PERSON', `no I/me/my/we/our on any line Kristy speaks: "${line}"`);
    }
    if (/—/.test(line)) fail('PICK_LINE_EM_DASH', `no em-dash asides: "${line}"`);
    // No digits. A number is a measurement, and a measurement is a claim with a source a
    // list row cannot show. "Heavy for its size", never "over 200g".
    if (/\d/.test(line)) fail('PICK_LINE_DIGIT', `no digits on a pick line: "${line}"`);
  const d = [];
  if (A.length !== B.length) d.push('length');
  for (const o of A) {
    const n = B.find((e) => e.id === o.id) ?? {};
    for (const k of new Set([...Object.keys(o), ...Object.keys(n)])) if (JSON.stringify(o[k]) !== JSON.stringify(n[k])) d.push(`${o.id}.${k}`);
  }
  // K3-1: salmon_wild_vs_farmed.aliases (salmon cuts) and farmed_fish_by_species.aliases (smoked shellfish) mirror the KB.
  assert.deepEqual([...d].sort(), ['produce_seasonality.aliases', 'produce_ripeness_by_item.aliases', 'produce_ripeness_by_item.asked_as', 'salmon_wild_vs_farmed.aliases', 'farmed_fish_by_species.aliases'].sort());
});

